corporate_design.toad_component_blueprint:
canvas {
  size: 900px 580px;
  fill: #FEF3C7;
  font-family: "Barlow, serif";
}

>hopGreen = #166534;
>beerGold = #D97706;
>wood = #292524;

rect #brewCard {
  at: center of canvas;
  size: 800px 480px;
  fill: #FFFFFF;
  stroke: >hopGreen;
  stroke-width: 2px;
  radius: 6px;
}

text #brewHeader {
  at: top center of #brewCard offset 0px 40px;
  content: "BRAUHAUS HOPFENSTOLZ • SEIT 1882";
  font-size: 16px;
  font-weight: 700;
  color: >beerGold;
}

text #brewTitle {
  at: below #brewHeader offset 16px;
  content: "Ungespundetes Fränkisches Kellerbier";
  font-size: 30px;
  font-weight: 700;
  color: >hopGreen;
}
